using Api.Models;
using Api.Services;
using Microsoft.AspNetCore.Mvc;

namespace Api.Controllers;

[ApiController]
public class OrdersController : ControllerBase
{
    private readonly IOrderService _orders;

    public OrdersController(IOrderService orders) => _orders = orders;

    [HttpPost("/orders")]
    public async Task<IActionResult> Create(CreateOrder cmd)
    {
        var id = await _orders.CreateAsync(cmd);
        return CreatedAtAction(nameof(GetById), new { id }, cmd);
    }

    [HttpDelete("/orders/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id)
    {
        if (!await _orders.DeleteAsync(id)) return NotFound();
        await _audit.EmitAsync("order.deleted", id);
        return NoContent();
    }
}

